from types import SimpleNamespace
six = SimpleNamespace(moves=SimpleNamespace(filter=filter))
PENDING, RUNNING = "PENDING", "RUNNING"

class Worker:
    def get_pending_tasks(self, state):
        """
        Get PENDING (and RUNNING) tasks for this worker.

        You have to pass in the state for optimization reasons.
        """
        if len(self.tasks) < state.num_pending_tasks():
            return six.moves.filter(lambda task: task.status in [PENDING, RUNNING],
                                    self.tasks)
        else:
            return state.get_pending_tasks()


def solve(worker_id, rows):
    tasks = [SimpleNamespace(id=identifier, status=status, workers=workers) for identifier, status, workers in rows]
    worker = Worker()
    worker.id = worker_id
    worker.tasks = [task for task in tasks if worker_id in task.workers]
    pending = [task for task in tasks if task.status in (PENDING, RUNNING)]
    state = SimpleNamespace(num_pending_tasks=lambda: len(pending), get_pending_tasks=lambda: iter(pending))
    return sorted(task.id for task in worker.get_pending_tasks(state))
